      enabled = bool
    }))
  })

hosted_system_profile.tfType:
object({
    enabled               = optional(bool)
    node_subnet_id        = optional(string)
    system_node_subnet_id = optional(string)
  })

kube_proxy_config.tfType:
object({
    enabled = bool
    mode    = optional(string)
