    config = optional(object({
      enable_secret_rotation = optional(bool, false)
      rotation_poll_interval = optional(string)
    }))
    enabled = bool
  })

ingress_profile.tfType:
object({
    gateway_api = optional(object({
      installation = optional(string)
    }))
